package com.tecsup.cita.model;import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity@Table(name="atencion")public class Atencion{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="id_atencion")private Long id;@OneToOne(optional=false)@JoinColumn(name="id_cita",unique=true)private Cita cita;@Lob private String diagnostico;@Lob private String tratamiento;@Lob private String observaciones;private LocalDateTime fechaRegistro=LocalDateTime.now();public Long getId(){return id;}public Cita getCita(){return cita;}public void setCita(Cita x){cita=x;}public String getDiagnostico(){return diagnostico;}public void setDiagnostico(String x){diagnostico=x;}public String getTratamiento(){return tratamiento;}public void setTratamiento(String x){tratamiento=x;}public String getObservaciones(){return observaciones;}public void setObservaciones(String x){observaciones=x;}public LocalDateTime getFechaRegistro(){return fechaRegistro;}}
